<script setup>
import{ref,onMounted}from'vue';
import{requestApi}from'../../shared/infrastructure/http/apiClient.js';
import{apiUrl}from'../../shared/infrastructure/http/apiUrl.js';
import{submitOperation,pendingOperations,retryOperation}from'../../shared/infrastructure/http/pendingOperation.js';
const props=defineProps({identity:Object,online:Boolean}),dashboard=ref(null),report=ref(null),exports=ref([]),error=ref(''),notice=ref(''),busy=ref(false),pending=ref([]);
const from=ref(new Date(Date.now()-7*86400000).toISOString().slice(0,10)),to=ref(new Date(Date.now()+86400000).toISOString().slice(0,10));
const can=p=>props.identity.permissions.includes(p),scope=()=>({tenantId:props.identity.tenantId,userId:props.identity.userId,resourceId:'reporting'});
const range=()=>({from:new Date(from.value+'T00:00:00Z').toISOString(),to:new Date(to.value+'T00:00:00Z').toISOString()});
async function load(){error.value='';try{dashboard.value=await requestApi('/api/v1/reporting/dashboard');if(can('reporting.export'))exports.value=(await requestApi('/api/v1/reporting/exports')).exports;pending.value=pendingOperations(scope());}catch(e){error.value=e.message;}}
onMounted(load);
async function losses(){busy.value=true;error.value='';try{report.value=await requestApi('/api/v1/reporting/losses?'+new URLSearchParams(range()));}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function exportEvidence(){busy.value=true;error.value='';try{const result=await submitOperation('/api/v1/reporting/exports',range(),scope(),'export');notice.value=result.state==='Ready'?'Exportación disponible.':'Exportación pendiente. Puedes consultar su estado y descargarla cuando finalice.';await load();}catch(e){error.value=e.message;pending.value=pendingOperations(scope());}finally{busy.value=false;}}
async function refreshExport(id){try{const result=await requestApi('/api/v1/reporting/exports/'+id);exports.value=exports.value.map(e=>e.exportId===id?result:e);}catch(e){error.value=e.message;}}
async function download(item){try{const response=await fetch(apiUrl(item.downloadUrl),{credentials:'include'});if(response.status===202){notice.value='Exportación pendiente; consulta nuevamente en unos segundos.';return;}if(!response.ok)throw Error('No se pudo descargar la exportación autorizada.');const url=URL.createObjectURL(await response.blob()),anchor=document.createElement('a');anchor.href=url;anchor.download=`eventore-evidence-${item.exportId}.csv`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=e.message;}}
async function retry(attempt){try{await retryOperation(attempt);await load();}catch(e){error.value=e.message;}}
</script>
<template><section class="panel" aria-label="Reportes"><h2>Operaciones y reportes</h2><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert" role="status">{{notice}}</p><p v-for="attempt in pending" :key="attempt.key" class="alert">Solicitud sin confirmar. <button @click="retry(attempt)">Reintentar reporte</button></p>
 <button class="secondary" :disabled="!online||busy" @click="load">Actualizar tablero</button><template v-if="dashboard"><p>Actualizado: {{new Date(dashboard.updatedAt).toLocaleString('es-PE')}}</p><p class="muted">{{dashboard.scope}}. Las capturas locales pendientes no están consolidadas aquí.</p><div class="metric-grid"><div><strong>{{dashboard.total}}</strong><span>Lotes aceptados</span></div><div><strong>{{dashboard.active}}</strong><span>Lotes activos</span></div><div v-for="(count,state) in dashboard.states" :key="state"><strong>{{count}}</strong><span>{{state}}</span></div></div><details><summary>Estados de los lotes</summary><ul><li v-for="lot in dashboard.lots" :key="lot.lotId">{{lot.lotId}} · {{lot.status}} · {{lot.originEvidenceStatus}}</li></ul></details></template>
 <div class="formrow"><label>Periodo desde (UTC)<input v-model="from" type="date" required /></label><label>Periodo hasta exclusivo (UTC)<input v-model="to" type="date" required /></label></div>
 <button :disabled="busy||!online" @click="losses">Consultar mermas técnicas</button><template v-if="report"><h3>Merma técnica ponderada: {{report.weightedLossPercentage}} %</h3><p>Entrada {{report.inputGrams}} g · merma {{report.lossGrams}} g</p><p class="muted">{{report.interpretation}}</p><ul><li v-for="operation in report.operations" :key="operation.operationId"><strong>{{operation.lossPercentage}} % · {{operation.critical?'Requiere investigación':'Dentro del umbral'}}</strong><p>{{operation.lossGrams}} g de {{operation.inputGrams}} g · {{operation.reason}}</p><p>{{operation.interpretation}}</p><p class="identifier">{{operation.operationId}}</p></li></ul><p v-if="!report.operations.length">Sin mermas técnicas en el periodo.</p></template>
 <template v-if="can('reporting.export')"><h3>Exportación de evidencias</h3><p>El CSV incluye las fuentes y el estado de revisión de los lotes del periodo. Aporta evidencia para revisión y no acredita por sí solo cumplimiento normativo ESG.</p><button :disabled="busy||!online" @click="exportEvidence">Solicitar exportación CSV</button><ul class="history-list"><li v-for="item in exports" :key="item.exportId"><strong>{{item.state==='Ready'?'Disponible':'Pendiente'}}</strong><p>{{item.from}} a {{item.to}}</p><p class="identifier">{{item.exportId}}</p><button v-if="item.state!=='Ready'" class="secondary" @click="refreshExport(item.exportId)">Consultar estado de exportación</button><button v-if="item.state==='Ready'" @click="download(item)">Descargar CSV</button></li></ul></template>
</section></template>
